def first_bad(commits, is_bad):
    lo, hi = 0, len(commits) - 1      # lo — хороший, hi — плохой
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if is_bad(commits[mid]):
            hi = mid
        else:
            lo = mid
    return commits[hi]
